import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as s,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Codex Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/codex/codex-glossary.md","filePath":"products/ai-coding/codex/codex-glossary.md","lastUpdated":1787044708000}'),r={name:"products/ai-coding/codex/codex-glossary.md"};function n(i,e,d,c,l,p){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="codex-glossary" tabindex="-1">Codex Glossary <a class="header-anchor" href="#codex-glossary" aria-label="Permalink to &quot;Codex Glossary&quot;">​</a></h1><blockquote><p>This is an <strong>explanation-oriented</strong> document. It answers &quot;what is this concept, why was it designed this way, and when should I use it.&quot; It complements the <a href="./codex-cheatsheet.html">Codex Cheatsheet</a>: the cheatsheet tells you <em>how to write the command</em>, this page tells you <em>why</em>.</p><p><strong>Single source of truth for definitions.</strong> Every Codex concept used across this site is defined here. Other pages show usage and link back rather than re-defining terms.</p><p><strong>Docs site moved.</strong> The official Codex documentation migrated from <code>developers.openai.com/codex/*</code> to <strong><code>learn.chatgpt.com/docs</code></strong>. Old URLs return a 308 permanent redirect. Every official link on this page uses the new host.</p></blockquote><h2 id="how-the-pieces-fit-together" tabindex="-1">How the pieces fit together <a class="header-anchor" href="#how-the-pieces-fit-together" aria-label="Permalink to &quot;How the pieces fit together&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                        ┌─────────────────────────┐</span></span>
<span class="line"><span>                        │   requirements.toml     │  admin-managed policy</span></span>
<span class="line"><span>                        │   org-wide constraints   │  (outermost limit)</span></span>
<span class="line"><span>                        └────────────┬────────────┘</span></span>
<span class="line"><span>                                     │ narrows what&#39;s selectable</span></span>
<span class="line"><span>                                     ▼</span></span>
<span class="line"><span>   ┌──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>   │                    config.toml  layer                         │</span></span>
<span class="line"><span>   │   ~/.codex/config.toml (user)  &gt;  .codex/config.toml (project) │</span></span>
<span class="line"><span>   │   Profiles: $CODEX_HOME/&lt;name&gt;.config.toml                     │</span></span>
<span class="line"><span>   └───────┬──────────────────────────┬───────────────────────────┘</span></span>
<span class="line"><span>           │                          │</span></span>
<span class="line"><span>           ▼                          ▼</span></span>
<span class="line"><span>   ┌───────────────┐          ┌──────────────────┐</span></span>
<span class="line"><span>   │  Permissions  │          │  Context &amp; rules │</span></span>
<span class="line"><span>   │  &amp; sandbox    │          │  ─────────────   │</span></span>
<span class="line"><span>   │  ───────────  │          │  AGENTS.md       │  ← project briefing</span></span>
<span class="line"><span>   │  approval_    │          │  Rules           │  ← structured limits</span></span>
<span class="line"><span>   │  policy       │          │  Memories        │  ← cross-session recall</span></span>
<span class="line"><span>   │  sandbox_mode │          │  Compaction      │  ← context compression</span></span>
<span class="line"><span>   │  trust_level  │          │                  │</span></span>
<span class="line"><span>   └───────┬───────┘          └────────┬─────────┘</span></span>
<span class="line"><span>           │                           │</span></span>
<span class="line"><span>           └───────────┬───────────────┘</span></span>
<span class="line"><span>                       ▼</span></span>
<span class="line"><span>           ┌───────────────────────┐</span></span>
<span class="line"><span>           │   Codex agent runtime │</span></span>
<span class="line"><span>           │   (a session)         │</span></span>
<span class="line"><span>           └───────────┬───────────┘</span></span>
<span class="line"><span>                       │ extended through</span></span>
<span class="line"><span>       ┌───────────────┼───────────────┬──────────────┐</span></span>
<span class="line"><span>       ▼               ▼               ▼              ▼</span></span>
<span class="line"><span>   ┌────────┐     ┌─────────┐    ┌─────────┐   ┌───────────┐</span></span>
<span class="line"><span>   │  MCP   │     │ Skills  │    │  Hooks  │   │ Subagents │</span></span>
<span class="line"><span>   │ outside│     │reusable │    │lifecycle│   │ delegated │</span></span>
<span class="line"><span>   │ tools  │     │workflows│    │  gates  │   │  agents   │</span></span>
<span class="line"><span>   └───┬────┘     └────┬────┘    └─────────┘   └───────────┘</span></span>
<span class="line"><span>       │               │</span></span>
<span class="line"><span>       └───────┬───────┘</span></span>
<span class="line"><span>               ▼</span></span>
<span class="line"><span>        ┌─────────────┐</span></span>
<span class="line"><span>        │   Plugins   │  packages MCP / Skills / Hooks for distribution</span></span>
<span class="line"><span>        └─────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   Surfaces (one config model, four entry points):</span></span>
<span class="line"><span>   CLI (codex) │ IDE extension │ Desktop app │ Web / Cloud</span></span></code></pre></div><p><strong>The organizing idea:</strong> the outer ring is <strong>constraint</strong> (managed policy → config files → permissions and sandbox), the middle ring is <strong>context</strong> (AGENTS.md, Rules, Memories decide what Codex <em>knows</em>), and the inner ring is <strong>capability</strong> (MCP, Skills, Hooks, Subagents decide what Codex <em>can do</em>). Plugins add no capability of their own; they are a distribution format for the other three.</p><p>The practical payoff: when Codex behaves unexpectedly, walk the rings outside-in — constraint, then context, then capability. That beats changing config keys at random.</p><hr><h2 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to &quot;AGENTS.md&quot;">​</a></h2><p><strong>What it is</strong></p><p>A Markdown file in your repository that tells Codex the conventions of the project in plain language: which package manager to use, what to run after changing code, which directories to leave alone. Think of it as the onboarding note you&#39;d hand a new teammate, except the reader is an agent.</p><p><strong>Why it exists</strong></p><p>Without it you re-explain &quot;this project uses pnpm, not npm&quot; in every conversation. With it, those conventions become context that loads automatically on every run.</p><p><strong>How it works: the instruction chain</strong></p><p>Codex builds an <strong>instruction chain</strong> before doing any work — once per run, and in the TUI once per launched session. Discovery order:</p><ol><li><strong>Global scope.</strong> In the Codex home directory (<code>~/.codex</code> by default, overridable with <code>CODEX_HOME</code>), Codex reads <code>AGENTS.override.md</code> if present, otherwise <code>AGENTS.md</code>. Only the <strong>first non-empty file</strong> at this level is used.</li><li><strong>Project scope.</strong> Starting at the project root (usually the Git root), Codex walks <strong>down</strong> to your current working directory. In each directory along the way it checks <code>AGENTS.override.md</code>, then <code>AGENTS.md</code>, then any name listed in <code>project_doc_fallback_filenames</code>. <strong>At most one file per directory</strong> is included.</li><li><strong>Merge order.</strong> Files are concatenated root-first, joined by blank lines. <strong>Files closer to your working directory appear later, so they override earlier guidance.</strong></li></ol><p>Empty files are skipped, and Codex stops adding files once the combined size reaches <code>project_doc_max_bytes</code> (<strong>32 KiB by default</strong>).</p><p><strong>Details worth knowing</strong></p><table tabindex="0"><thead><tr><th>Detail</th><th>Notes</th></tr></thead><tbody><tr><td>Override, not merge</td><td>When <code>AGENTS.override.md</code> exists, the sibling <code>AGENTS.md</code> is ignored</td></tr><tr><td>Walks down, never up</td><td>Root → cwd only; directories past cwd are not considered</td></tr><tr><td>Custom filenames</td><td><code>project_doc_fallback_filenames = [&quot;TEAM_GUIDE.md&quot;, &quot;.agents.md&quot;]</code></td></tr><tr><td>Raise the ceiling</td><td><code>project_doc_max_bytes = 65536</code></td></tr><tr><td>Review rules</td><td>Add a <code>## Code Review Rules</code> section to the <code>AGENTS.md</code> nearest the code it governs</td></tr><tr><td>Temporary global override</td><td>Drop in <code>~/.codex/AGENTS.override.md</code>; delete it to restore the base file</td></tr></tbody></table><p><strong>AGENTS.md vs. Rules</strong></p><table tabindex="0"><thead><tr><th>Dimension</th><th>AGENTS.md</th><th>Rules</th></tr></thead><tbody><tr><td>Form</td><td>Natural-language Markdown</td><td>Structured rule configuration</td></tr><tr><td>Purpose</td><td>Convey conventions and background</td><td>Declare constraints and checks</td></tr><tr><td>Scoping</td><td>Inherits and overrides per directory</td><td>Matches per rule entry</td></tr></tbody></table><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/agent-configuration/agents-md" target="_blank" rel="noreferrer">Custom instructions with AGENTS.md</a></p><hr><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p><strong>What it is</strong></p><p>A more structured constraint mechanism than AGENTS.md, used to declare what must or must not happen under given conditions. Project-level Rules live in the <code>.codex/</code> project layer and are therefore gated by project trust.</p><p><strong>Why it exists</strong></p><p>AGENTS.md is prose, and prose can be misread. Rules give constraints a more explicit form, which also makes them easier to distribute across a team and to audit. <code>/debug-config</code> shows which rules are actually in effect.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/agent-configuration/rules" target="_blank" rel="noreferrer">Rules</a></p><hr><h2 id="sandbox" tabindex="-1">Sandbox <a class="header-anchor" href="#sandbox" aria-label="Permalink to &quot;Sandbox&quot;">​</a></h2><p><strong>What it is</strong></p><p>The isolation layer that decides which files Codex can read or write and whether it can reach the network. It is the <strong>mechanism</strong> dimension — what is technically possible — and it is independent from approval policy, which decides whether Codex asks you first.</p><p><strong>The three modes</strong></p><table tabindex="0"><thead><tr><th><code>sandbox_mode</code></th><th>Meaning</th><th>Typical use</th></tr></thead><tbody><tr><td><code>read-only</code></td><td>Cannot modify files</td><td>Code review, architecture analysis</td></tr><tr><td><code>workspace-write</code></td><td>Can write within the workspace</td><td>Everyday development</td></tr><tr><td><code>danger-full-access</code></td><td>No sandbox restrictions</td><td>Only when you accept the risk knowingly</td></tr></tbody></table><p><code>workspace-write</code> can be tuned further:</p><table tabindex="0"><thead><tr><th>Key</th><th>Effect</th></tr></thead><tbody><tr><td><code>sandbox_workspace_write.writable_roots</code></td><td>Add writable roots</td></tr><tr><td><code>sandbox_workspace_write.network_access</code></td><td>Allow network access</td></tr><tr><td><code>sandbox_workspace_write.exclude_slash_tmp</code></td><td>Remove <code>/tmp</code> from the writable set</td></tr><tr><td><code>sandbox_workspace_write.exclude_tmpdir_env_var</code></td><td>Remove <code>$TMPDIR</code> from the writable set</td></tr></tbody></table><p><strong>Why sandbox and approval are separate concerns</strong></p><p>They are two independent lines of defense. The sandbox is a <strong>hard boundary</strong> that cannot be crossed; approval is a <strong>human gate</strong> you pass through deliberately. Approval without a sandbox means one careless &quot;yes&quot; can do damage. A sandbox without approval means Codex acts freely inside the boundary while you have no visibility. You want both.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/sandboxing" target="_blank" rel="noreferrer">Sandboxing</a></p><hr><h2 id="approval-policy-and-permissions" tabindex="-1">Approval policy and permissions <a class="header-anchor" href="#approval-policy-and-permissions" aria-label="Permalink to &quot;Approval policy and permissions&quot;">​</a></h2><p><strong>What it is</strong></p><p>The policy that decides whether Codex asks before acting. Note that the config layer and the UI layer use <strong>two different vocabularies</strong> — this is the single most common source of confusion.</p><p><strong>Config layer: <code>approval_policy</code></strong></p><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>untrusted</code></td><td>Auto-runs only operations considered safe; asks about everything else</td></tr><tr><td><code>on-request</code></td><td>The model requests approval when it judges it necessary</td></tr><tr><td><code>never</code></td><td>Never asks</td></tr><tr><td><code>{ granular = { ... } }</code></td><td>Fine-grained control over <code>sandbox_approval</code>, <code>rules</code>, <code>mcp_elicitations</code>, <code>request_permissions</code>, and <code>skill_approval</code></td></tr></tbody></table><blockquote><p>The legacy value <code>on-failure</code> is deprecated. On the command line, <code>--ask-for-approval &lt;policy&gt;</code> sets this for a single run.</p></blockquote><p><strong>UI layer: TUI permission modes</strong></p><p>Inside the TUI, <code>/permissions</code> switches between three presets: <strong>Auto</strong> (default), <strong>Read-only</strong>, and <strong>Full Access</strong>.</p><p><strong>Why two vocabularies</strong></p><p>The config layer describes <em>how approval requests are generated</em>. The UI layer describes <em>practical presets</em> — Read-only and Full Access adjust both the sandbox and the approval dimension at once. When writing docs or debugging with a teammate, always say which layer you mean, or the conversation will go sideways.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/permissions" target="_blank" rel="noreferrer">Permissions</a></p><hr><h2 id="project-trust-and-config-layering" tabindex="-1">Project trust and config layering <a class="header-anchor" href="#project-trust-and-config-layering" aria-label="Permalink to &quot;Project trust and config layering&quot;">​</a></h2><p><strong>What it is</strong></p><p>Whether Codex trusts a given project directory, configured as <code>projects.&lt;path&gt;.trust_level</code> with the values <code>&quot;trusted&quot;</code> or <code>&quot;untrusted&quot;</code>.</p><p><strong>Why it exists</strong></p><p>The <code>.codex/</code> directory is <strong>content anyone can commit to a repository</strong>. If cloning an unfamiliar repo automatically loaded its config, hooks, and rules, you would be handing execution to whoever wrote it. Trust gating is the defense: <strong>untrusted projects skip every project-level <code>.codex/</code> layer</strong> — config, hooks, and rules are all ignored.</p><p><strong>Precedence</strong></p><p>Official <a href="https://learn.chatgpt.com/docs/config-file/config-basic" target="_blank" rel="noreferrer">config basics</a> resolve values in this order (highest first):</p><ol><li>CLI flags and <code>-c</code> / <code>--config</code> overrides</li><li>Project <code>.codex/config.toml</code> files, root → cwd, closest wins — <strong>trusted projects only</strong></li><li>Profile file selected with <code>--profile</code> (<code>$CODEX_HOME/&lt;name&gt;.config.toml</code>)</li><li>User config: <code>~/.codex/config.toml</code></li><li>System config, if present: <code>/etc/codex/config.toml</code> on Unix</li><li>Built-in defaults</li></ol><p>A trusted project&#39;s config <strong>does</strong> override the matching keys in your user config. That is the official order. What project config <em>cannot</em> do is a separate rule: a short list of machine-local keys is <strong>ignored</strong> at project scope.</p><p><code>openai_base_url</code>, <code>chatgpt_base_url</code>, <code>apps_mcp_product_sku</code>, <code>model_provider</code>, <code>model_providers</code>, <code>notify</code>, <code>profile</code>, <code>profiles</code>, <code>experimental_realtime_ws_base_url</code>, <code>otel</code></p><p>The intent is blunt and correct: <strong>a repository must not be able to silently reroute your model requests to another endpoint.</strong></p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Config Reference</a></p><hr><h2 id="profiles" tabindex="-1">Profiles <a class="header-anchor" href="#profiles" aria-label="Permalink to &quot;Profiles&quot;">​</a></h2><p><strong>What it is</strong></p><p>A named bundle of configuration for switching between contexts — a work setup versus a personal sandbox, say.</p><p><strong>How it works</strong></p><p>Profile files sit next to <code>config.toml</code> as <code>$CODEX_HOME/&lt;profile-name&gt;.config.toml</code>, selected with <code>--profile &lt;profile-name&gt;</code>.</p><p><strong>Profiles vs. <code>CODEX_HOME</code></strong></p><table tabindex="0"><thead><tr><th>Dimension</th><th>Profile</th><th><code>CODEX_HOME</code></th></tr></thead><tbody><tr><td>What switches</td><td>One config inside the same home</td><td>The entire Codex home directory</td></tr><tr><td>Isolation</td><td>Config only</td><td>Config, sessions, and logs</td></tr><tr><td>Typical use</td><td>Two model/permission setups</td><td>A separate automation identity in CI</td></tr></tbody></table><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Config Reference</a>, <a href="https://learn.chatgpt.com/docs/config-file/environment-variables" target="_blank" rel="noreferrer">Environment Variables</a></p><hr><h2 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h2><p><strong>What it is</strong></p><p>An open protocol that lets Codex connect to external tools and data sources. The useful analogy is a USB port: once the protocol is standard, any service that implements it works with Codex, and Codex does not need bespoke integration code per service.</p><p><strong>Why it matters</strong></p><p>Without MCP, an agent can only read local files and run commands. With it, the same agent can query a database, call an internal API, or read design files — and the providers of those capabilities stay decoupled from Codex itself.</p><p><strong>Configuration shape (correcting a common error)</strong></p><p><code>mcp_servers</code> is a <strong>table keyed by server id</strong>, not an array of tables:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp_servers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">filesystem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">command = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">args = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@modelcontextprotocol/server-filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Common keys:</p><table tabindex="0"><thead><tr><th>Key</th><th>Notes</th></tr></thead><tbody><tr><td><code>command</code> / <code>args</code> / <code>cwd</code> / <code>env</code></td><td>Launch a local process over STDIO</td></tr><tr><td><code>url</code> / <code>http_headers</code> / <code>bearer_token_env_var</code></td><td>Connect to a remote server over streaming HTTP</td></tr><tr><td><code>enabled</code> / <code>required</code></td><td>Whether the server is on, and whether it&#39;s mandatory</td></tr><tr><td><code>enabled_tools</code> / <code>disabled_tools</code></td><td>Per-tool allow/deny lists</td></tr><tr><td><code>default_tools_approval_mode</code></td><td><code>auto</code> / <code>prompt</code> / <code>approve</code></td></tr><tr><td><code>startup_timeout_sec</code></td><td>Startup timeout, default 10</td></tr><tr><td><code>tool_timeout_sec</code></td><td>Per-call timeout, default 60</td></tr></tbody></table><p><strong>Codex plays both roles</strong></p><p>Codex can act as an MCP <strong>client</strong> consuming other services, and as an MCP <strong>server</strong> that other agents call (see <code>codex mcp</code> and the MCP Server docs).</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/extend/mcp?surface=cli" target="_blank" rel="noreferrer">MCP</a>, <a href="https://learn.chatgpt.com/docs/mcp-server" target="_blank" rel="noreferrer">MCP Server</a></p><hr><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><p><strong>What it is</strong></p><p>A reusable workflow packaged so Codex can invoke it at the right moment. <code>/skills</code> lists what&#39;s available.</p><p><strong>Skills vs. MCP</strong></p><table tabindex="0"><thead><tr><th>Dimension</th><th>Skills</th><th>MCP</th></tr></thead><tbody><tr><td>Essence</td><td>Packaged <strong>process / know-how</strong></td><td>Connected <strong>tools / data</strong></td></tr><tr><td>Who executes</td><td>Codex follows the process</td><td>An external service runs and returns</td></tr><tr><td>Typical content</td><td>&quot;Our release process has seven steps&quot;</td><td>&quot;Query the production database&quot;</td></tr></tbody></table><p>Quick test: needing to <strong>reach an external system</strong> means MCP; needing to <strong>codify a way of working</strong> means Skills.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/build-skills" target="_blank" rel="noreferrer">Skills</a></p><hr><h2 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;Hooks&quot;">​</a></h2><p><strong>What it is</strong></p><p>Commands that fire automatically at specific points in the Codex lifecycle, used for enforced checks or automation. They can be declared inline in <code>config.toml</code>.</p><p><strong>Supported events</strong></p><p><code>PreToolUse</code>, <code>PermissionRequest</code>, <code>PostToolUse</code>, <code>PreCompact</code>, <code>PostCompact</code>, <code>SessionStart</code>, <code>SubagentStart</code>, <code>SubagentStop</code>, <code>UserPromptSubmit</code>, <code>Stop</code></p><p><strong>Current limitation:</strong> only command hooks execute. Prompt and agent hook types are parsed but skipped. For platform differences, <code>commandWindows</code> (written as <code>command_windows</code> in TOML) supplies a Windows-specific command.</p><p><strong>Hooks vs. AGENTS.md</strong></p><p>AGENTS.md is <strong>advice</strong> — the model may not follow it. Hooks are <strong>enforcement</strong> — the script always runs. Requirements like &quot;code must be formatted after every change&quot; belong in Hooks, not in prose.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/hooks" target="_blank" rel="noreferrer">Hooks</a></p><hr><h2 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h2><p><strong>What it is</strong></p><p>A packaging format that bundles MCP servers, Skills, and Hooks into one distributable unit. Managed with <code>/plugins</code>.</p><p><strong>Why it exists</strong></p><p>Asking every teammate to configure MCP plus Skills plus Hooks by hand does not scale and invites drift. Plugins turn &quot;a working Codex environment&quot; into something you install once.</p><p><strong>Ecosystem role:</strong> Plugins are a <strong>distribution layer</strong> and introduce no new capability. Configuration can override the enablement and tool approval modes of the MCP servers they bundle, via <code>plugins.&lt;plugin&gt;.mcp_servers.&lt;server&gt;.*</code>.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/plugins" target="_blank" rel="noreferrer">Plugins</a></p><hr><h2 id="subagents" tabindex="-1">Subagents <a class="header-anchor" href="#subagents" aria-label="Permalink to &quot;Subagents&quot;">​</a></h2><p><strong>What it is</strong></p><p>Independent agents spawned by the main agent, used for parallelism or context isolation. Managed with <code>/agent</code> and declared in the <code>[agents]</code> config section.</p><p><strong>Key behavior:</strong> subagents are <strong>spawned only when you explicitly ask</strong> — never automatically.</p><p><strong>Related configuration</strong></p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>agents.max_depth</code></td><td>1</td><td>Maximum nesting depth</td></tr><tr><td><code>agents.max_threads</code></td><td>6</td><td>Maximum concurrent threads</td></tr><tr><td><code>agents.job_max_runtime_seconds</code></td><td>1800</td><td>Per-job runtime cap</td></tr><tr><td><code>agents.&lt;name&gt;.config_file</code></td><td>—</td><td>Config file the subagent uses</td></tr><tr><td><code>agents.&lt;name&gt;.description</code></td><td>—</td><td>Description; influences when it is selected</td></tr></tbody></table><p>With <code>features.multi_agent</code> enabled, the available tools are <code>spawn_agent</code>, <code>send_input</code>, <code>resume_agent</code>, <code>wait_agent</code>, and <code>close_agent</code>.</p><p><strong>When to reach for them</strong></p><p>When you need <strong>context isolation</strong> — for example a subagent dedicated to adversarial review, so it isn&#39;t anchored by the main thread&#39;s reasoning — or genuine <strong>parallelism</strong> across independent tasks. Tightly coupled work is usually faster done serially.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/agent-configuration/subagents" target="_blank" rel="noreferrer">Subagents</a></p><hr><h2 id="memories" tabindex="-1">Memories <a class="header-anchor" href="#memories" aria-label="Permalink to &quot;Memories&quot;">​</a></h2><p><strong>What it is</strong></p><p>Information retained across sessions so Codex remembers your preferences and project background without being told again. Managed with <code>/memories</code>.</p><p><strong>Memories vs. AGENTS.md</strong></p><table tabindex="0"><thead><tr><th>Dimension</th><th>Memories</th><th>AGENTS.md</th></tr></thead><tbody><tr><td>Origin</td><td>Codex extracts, you confirm</td><td>You write it</td></tr><tr><td>Stored</td><td>On the Codex side</td><td>In the repo — committable, reviewable</td></tr><tr><td>Suits</td><td>Personal habits, accumulated experience</td><td>Team conventions everyone must share</td></tr></tbody></table><p>The test is simple: <strong>should the whole team share this?</strong> If yes, write it into AGENTS.md and commit it. If it&#39;s just how you like to work, leave it to Memories.</p><p><strong>Related configuration:</strong> <code>features.memories</code> (off by default); details under <code>memories.*</code>, including <code>use_memories</code>, <code>generate_memories</code>, <code>max_unused_days</code>, and <code>max_rollout_age_days</code>.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/customization/memories?surface=app" target="_blank" rel="noreferrer">Memories</a></p><hr><h2 id="sessions-and-compaction" tabindex="-1">Sessions and compaction <a class="header-anchor" href="#sessions-and-compaction" aria-label="Permalink to &quot;Sessions and compaction&quot;">​</a></h2><p><strong>What it is</strong></p><p>A continuous conversation and the context it accumulates. Session records live in <code>~/.codex/sessions/</code>.</p><p><strong>Session operations</strong></p><table tabindex="0"><thead><tr><th>Operation</th><th>Command</th></tr></thead><tbody><tr><td>Resume via picker</td><td><code>codex resume</code></td></tr><tr><td>Resume the latest</td><td><code>codex resume --last</code></td></tr><tr><td>Resume a specific session</td><td><code>codex resume &lt;SESSION_ID&gt;</code></td></tr><tr><td>List all</td><td><code>codex resume --all</code></td></tr><tr><td>Fork from current state</td><td><code>/fork</code></td></tr><tr><td>Archive / unarchive</td><td><code>/archive</code>, <code>codex unarchive &lt;SESSION&gt;</code></td></tr></tbody></table><p>Session IDs come from the picker, from <code>/status</code>, or from the <code>~/.codex/sessions/</code> directory.</p><p><strong>Compaction</strong></p><p>When context approaches its limit, earlier conversation is compressed into a summary to free space. <code>/compact</code> triggers it manually; the automatic threshold is <code>model_auto_compact_token_limit</code>. The <code>PreCompact</code> and <code>PostCompact</code> hook events let you act around the boundary.</p><p><strong>Why you should manage it yourself</strong></p><p>Compaction is lossy — summaries drop detail. Rather than waiting for it, <code>/clear</code> or start a fresh session when you switch tasks. One session per task is far more reliable than one session for ten tasks followed by forced compression.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/developer-commands?surface=cli" target="_blank" rel="noreferrer">Slash commands</a></p><hr><h2 id="web-search-modes" tabindex="-1">Web search modes <a class="header-anchor" href="#web-search-modes" aria-label="Permalink to &quot;Web search modes&quot;">​</a></h2><p><strong>What it is</strong></p><p>How Codex reaches external web information. There are four documented values — and importantly, this is an <strong>enum string</strong>, not a boolean toggle.</p><table tabindex="0"><thead><tr><th><code>web_search</code></th><th>Meaning</th></tr></thead><tbody><tr><td><code>disabled</code></td><td>Off</td></tr><tr><td><code>cached</code></td><td><strong>Default.</strong> Queries an OpenAI-maintained index rather than fetching live</td></tr><tr><td><code>indexed</code></td><td>External web access only when the search index gates the request</td></tr><tr><td><code>live</code></td><td>Fetches live; becomes the default under <code>--yolo</code> / full-access mode</td></tr></tbody></table><p>On the command line, a <strong>bare <code>--search</code></strong> (no argument) enables live search. Results appear as <code>web_search</code> items in the transcript and in <code>codex exec --json</code> output.</p><blockquote><p>The legacy toggles <code>features.web_search</code>, <code>features.web_search_cached</code>, and <code>features.web_search_request</code> are deprecated.</p></blockquote><p><strong>Why cached is the default</strong></p><p>The cached index is faster and cheaper, and it is sufficient for the vast majority of &quot;how does this API work&quot; questions. <code>live</code> earns its cost only when you need genuinely fresh information, such as a release published this week.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Config Reference</a></p><hr><h2 id="non-interactive-mode-codex-exec" tabindex="-1">Non-interactive mode (<code>codex exec</code>) <a class="header-anchor" href="#non-interactive-mode-codex-exec" aria-label="Permalink to &quot;Non-interactive mode (\`codex exec\`)&quot;">​</a></h2><p><strong>What it is</strong></p><p>A run mode that skips the TUI, completes one task, and exits. Built for scripts and CI.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;run the test suite and fix any failures&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;summarize recent changes&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --last</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;now add tests for the new function&quot;</span></span></code></pre></div><p><strong>Why it&#39;s a separate subcommand</strong></p><p>CI has no terminal to interact with, and should never block on a human approval prompt. <code>codex exec</code> states plainly that this is a one-shot unattended run: logging defaults to <code>RUST_LOG=error</code> and output is easy for a script to consume.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/non-interactive-mode" target="_blank" rel="noreferrer">Non-interactive Mode</a></p><hr><h2 id="surfaces-cli-ide-app-cloud" tabindex="-1">Surfaces: CLI, IDE, app, cloud <a class="header-anchor" href="#surfaces-cli-ide-app-cloud" aria-label="Permalink to &quot;Surfaces: CLI, IDE, app, cloud&quot;">​</a></h2><p><strong>What it is</strong></p><p>Four entry points to the same Codex agent. They share one configuration model — <code>config.toml</code>, AGENTS.md, MCP, Skills — and differ in interaction style and where the work runs.</p><table tabindex="0"><thead><tr><th>Surface</th><th>Entry point</th><th>Character</th></tr></thead><tbody><tr><td>CLI</td><td><code>codex</code></td><td>Terminal TUI; strongest scripting story</td></tr><tr><td>IDE extension</td><td>Inside your editor</td><td>Tied into editor context</td></tr><tr><td>Desktop app</td><td>Standalone application</td><td>GUI, multi-thread session management</td></tr><tr><td>Web / Cloud</td><td><code>codex cloud</code></td><td>Runs in a cloud environment; tasks can retry in parallel</td></tr></tbody></table><p><strong>Cloud commands</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                          # open the cloud UI (Ctrl+O reveals environment IDs)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENV_I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # run in a named cloud environment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ENV_I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --attempts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # retry the same task (1-4 attempts)</span></span></code></pre></div><p><strong>Remote control:</strong> start a server with <code>codex app-server --listen ws://127.0.0.1:4500</code> and connect with <code>codex --remote ws://127.0.0.1:4500</code>. <code>--remote</code> accepts <code>ws://</code>, <code>wss://</code>, and <code>unix://</code>. Anything crossing a network must use <code>wss://</code> with authentication configured.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/codex/cli" target="_blank" rel="noreferrer">CLI</a>, <a href="https://learn.chatgpt.com/docs/codex/ide" target="_blank" rel="noreferrer">IDE Extension</a>, <a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">App Server</a></p><hr><h2 id="requirements-toml-managed-policy" tabindex="-1">requirements.toml (managed policy) <a class="header-anchor" href="#requirements-toml-managed-policy" aria-label="Permalink to &quot;requirements.toml (managed policy)&quot;">​</a></h2><p><strong>What it is</strong></p><p>A policy file distributed by administrators to <strong>narrow</strong> what users may select. It is not &quot;another config file&quot; — it is the upper bound on configuration.</p><p><strong>What it can constrain</strong></p><table tabindex="0"><thead><tr><th>Key</th><th>Effect</th></tr></thead><tbody><tr><td><code>allowed_approval_policies</code></td><td>Permitted approval policies (e.g. <code>untrusted</code>, <code>on-request</code>, <code>never</code>, <code>granular</code>)</td></tr><tr><td><code>allowed_sandbox_modes</code></td><td>Permitted sandbox modes</td></tr><tr><td><code>allowed_web_search_modes</code></td><td>Permitted search modes; <code>disabled</code> is always allowed, and an empty list means only <code>disabled</code></td></tr><tr><td><code>allowed_permission_profiles</code></td><td>Permitted permission profiles; <strong>requires Codex 0.138.0+</strong></td></tr><tr><td><code>default_permissions</code></td><td>Default permission profile; must appear in the allowed list</td></tr><tr><td><code>allow_managed_hooks_only</code></td><td>Run managed hooks only, skipping user/project/session/plugin hooks</td></tr><tr><td><code>features.*</code></td><td>Pin feature flags using the same key names as <code>config.toml</code></td></tr><tr><td><code>mcp_servers</code> allowlist</td><td>Requires both an id and an <code>identity</code> (<code>identity.command</code> or <code>identity.url</code>)</td></tr><tr><td><code>marketplaces.*</code></td><td>Restrict plugin sources (<code>git</code> / <code>host_pattern</code> / <code>local</code>)</td></tr><tr><td><code>enforce_residency</code></td><td>Data residency; currently only <code>us</code> is supported</td></tr></tbody></table><blockquote><p><strong>Version note:</strong> Codex 0.137.0 and earlier ignore <code>allowed_permission_profiles</code> and managed <code>default_permissions</code>. If you rely on those for enforcement, confirm clients are on 0.138.0 or newer first.</p></blockquote><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/config-file/config-reference" target="_blank" rel="noreferrer">Config Reference</a></p><hr><h2 id="models-and-reasoning-effort" tabindex="-1">Models and reasoning effort <a class="header-anchor" href="#models-and-reasoning-effort" aria-label="Permalink to &quot;Models and reasoning effort&quot;">​</a></h2><p><strong>What it is</strong></p><p>The model Codex uses, and how long it is allowed to think.</p><table tabindex="0"><thead><tr><th>Key</th><th>Values</th><th>Notes</th></tr></thead><tbody><tr><td><code>model</code></td><td>string</td><td>The official config-basics example is <code>gpt-5.6</code>; names change — check <a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">Models</a></td></tr><tr><td><code>model_reasoning_effort</code></td><td><code>minimal</code> / <code>low</code> / <code>medium</code> / <code>high</code> / <code>xhigh</code></td><td>Responses API only</td></tr><tr><td><code>model_reasoning_summary</code></td><td><code>auto</code> / <code>concise</code> / <code>detailed</code> / <code>none</code></td><td>Verbosity of reasoning summaries</td></tr><tr><td><code>model_verbosity</code></td><td><code>low</code> / <code>medium</code> / <code>high</code></td><td>Verbosity of output</td></tr></tbody></table><p><code>--model &lt;name&gt;</code> overrides for one run; <code>/model</code> switches mid-session.</p><p><strong>Choosing an effort level</strong></p><p>Changing a config line or adding a log statement — <code>low</code> is plenty. Designing module boundaries or chasing a concurrency bug — <code>high</code> or <code>xhigh</code> is worth the wait. The <code>medium</code> default fits most daily work. Running everything at <code>xhigh</code> only makes easy tasks slow and burns through limits faster.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/models" target="_blank" rel="noreferrer">Models</a></p><hr><h2 id="chat-work-codex" tabindex="-1">Chat / Work / Codex <a class="header-anchor" href="#chat-work-codex" aria-label="Permalink to &quot;Chat / Work / Codex {#chat-work-codex}&quot;">​</a></h2><p><strong>What it is</strong></p><p>Three ways of working in one ChatGPT app, not three installers. Official comparison: <a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a>.</p><table tabindex="0"><thead><tr><th>Name</th><th>What it is</th><th>What it is not</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>Questions, short drafts, settling a design</td><td>Not a coding UI</td></tr><tr><td><strong>ChatGPT Work</strong></td><td>Take a task to a reviewable file (deck / sheet / site / recurring update)</td><td>Not Codex; no PR sidebar</td></tr><tr><td><strong>Codex</strong></td><td>Coding agent: repo, diff, tests, PR</td><td>Not a chat box</td></tr></tbody></table><p>On 2026-07-09 the standalone Codex desktop app merged into the ChatGPT desktop app. Work and Codex share usage limits.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/use-chatgpt" target="_blank" rel="noreferrer">Use ChatGPT</a> · <a href="./chatgpt-work.html">ChatGPT Work</a></p><hr><h2 id="chatgpt-work" tabindex="-1">ChatGPT Work <a class="header-anchor" href="#chatgpt-work" aria-label="Permalink to &quot;ChatGPT Work {#chatgpt-work}&quot;">​</a></h2><p><strong>What it is</strong></p><p>Official wording: <em>ChatGPT Work is a way to delegate real work to ChatGPT.</em> Web Work runs in the cloud. The desktop app can <strong>Work locally</strong> against files and apps on the machine.</p><p><strong>Versus Codex</strong></p><p>Capabilities can overlap (official docs say you may keep using Codex for non-coding work). The interface does not: Work hides Git / shell and is built for everyday knowledge work. Frontend engineers use it for agendas, Sites, and Slack. Repo edits stay in Codex.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/get-started-with-work" target="_blank" rel="noreferrer">Get started with Work</a> · this guide’s <a href="./chatgpt-work.html">ChatGPT Work</a></p><hr><h2 id="sites" tabindex="-1">Sites <a class="header-anchor" href="#sites" aria-label="Permalink to &quot;Sites {#sites}&quot;">​</a></h2><p><strong>What it is</strong></p><p>A ChatGPT workflow that creates, hosts, and shares websites and apps. Public beta. Entry: <a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a>.</p><p><strong>What it is not</strong></p><p>Not Claude Design. There is no official “import a design system from the repo, then hand off a bundle” product. Every deploy URL is production.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites</a> · this guide’s <a href="./sites.html">Sites</a></p><hr><h2 id="codex-cloud" tabindex="-1">Codex Cloud and hosted review <a class="header-anchor" href="#codex-cloud" aria-label="Permalink to &quot;Codex Cloud and hosted review {#codex-cloud}&quot;">​</a></h2><p><strong>What it is</strong></p><p>Coding tasks in isolated OpenAI-hosted environments, in parallel, dispatchable from GitHub / Linear / Slack. Entry: <a href="https://chatgpt.com/codex" target="_blank" rel="noreferrer">chatgpt.com/codex</a>.</p><p><strong>Hosted review</strong></p><p>Cloud code review / QA is powered by <strong>GPT-5.6 Sol</strong> for eligible customers; Cloud selects the model. Codex Security Review is a separate research preview (Enterprise / Business / Edu / Pro, not Plus). Local <code>/review</code> is a session command — do not reuse the hosted-review name for it.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/cloud" target="_blank" rel="noreferrer">Codex cloud</a> · <a href="https://learn.chatgpt.com/docs/whats-new" target="_blank" rel="noreferrer">What&#39;s new</a> · this guide’s <a href="./codex-cloud.html">Cloud</a></p><hr><h2 id="codex-ide-extension" tabindex="-1">Codex IDE extension <a class="header-anchor" href="#codex-ide-extension" aria-label="Permalink to &quot;Codex IDE extension {#codex-ide-extension}&quot;">​</a></h2><p><strong>What it is</strong></p><p>The editor surface: open files and selections go into the prompt; you review a focused diff beside the source. Same config model as the CLI.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/codex/ide" target="_blank" rel="noreferrer">IDE</a> · this guide’s <a href="./codex-ide.html">IDE</a></p><hr><h2 id="codex-remote" tabindex="-1">Codex Remote <a class="header-anchor" href="#codex-remote" aria-label="Permalink to &quot;Codex Remote {#codex-remote}&quot;">​</a></h2><p><strong>What it is</strong></p><p>The phone (or another desktop) steers a <strong>paired</strong> Mac or Windows host. The host runs the work. Not Cloud.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/codex/remote" target="_blank" rel="noreferrer">Remote</a> · this guide’s <a href="./codex-remote.html">Remote</a></p><hr><h2 id="codex-security" tabindex="-1">Codex Security <a class="header-anchor" href="#codex-security" aria-label="Permalink to &quot;Codex Security {#codex-security}&quot;">​</a></h2><p><strong>What it is</strong></p><p>An application-security agent with three doors: desktop plugin, CLI/SDK (<code>@openai/codex-security</code>), and Cloud (research preview). Scan only code you are authorized to assess.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/codex/security" target="_blank" rel="noreferrer">Security</a> · this guide’s <a href="./codex-security.html">Security</a></p><hr><h2 id="chrome-extension" tabindex="-1">Chrome extension <a class="header-anchor" href="#chrome-extension" aria-label="Permalink to &quot;Chrome extension {#chrome-extension}&quot;">​</a></h2><p><strong>What it is</strong></p><p>Lets ChatGPT control <strong>your</strong> Chrome profile, including signed-in tabs. Distinct from <code>@Browser</code> (built-in profile) and Work’s signed-out cloud browser.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/codex/chrome-extension" target="_blank" rel="noreferrer">Chrome extension</a> · this guide’s <a href="./codex-chrome.html">Chrome</a></p><hr><h2 id="computer-use" tabindex="-1">Computer Use <a class="header-anchor" href="#computer-use" aria-label="Permalink to &quot;Computer Use {#computer-use}&quot;">​</a></h2><p><strong>What it is</strong></p><p>Desktop-app capability: ChatGPT sees and operates GUIs on macOS or Windows. Windows takes the foreground. File/shell still follow sandbox and approval.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/computer-use" target="_blank" rel="noreferrer">Computer Use</a></p><hr><h2 id="browser" tabindex="-1">Browser <a class="header-anchor" href="#browser" aria-label="Permalink to &quot;Browser {#browser}&quot;">​</a></h2><p><strong>What it is</strong></p><p>Either the desktop <strong>built-in</strong> browser (<code>@Browser</code>, separate profile) or Work’s <strong>cloud</strong> browser (signed-out public sites). Not available in CLI or the IDE extension.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/browser" target="_blank" rel="noreferrer">Browser</a></p><hr><h2 id="chatgpt-voice" tabindex="-1">ChatGPT Voice <a class="header-anchor" href="#chatgpt-voice" aria-label="Permalink to &quot;ChatGPT Voice {#chatgpt-voice}&quot;">​</a></h2><p><strong>What it is</strong></p><p>GPT-Live voice in Chat, Work, and Codex on the desktop app (and iOS Remote after pairing). A chat must <strong>start</strong> in voice mode. Separate rolling Voice allowance; tasks still spend Codex quota.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/features/voice" target="_blank" rel="noreferrer">Voice</a></p><hr><h2 id="computer-history" tabindex="-1">Computer History <a class="header-anchor" href="#computer-history" aria-label="Permalink to &quot;Computer History {#computer-history}&quot;">​</a></h2><p><strong>What it is</strong></p><p>macOS desktop feature (off by default) that turns allowed app/website activity into memories and a timeline. Needs Memories. Not in EEA / CH / UK. Replaces the Chronicle preview.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/customization/computer-history" target="_blank" rel="noreferrer">Computer History</a></p><hr><h2 id="codex-sdk" tabindex="-1">Codex SDK <a class="header-anchor" href="#codex-sdk" aria-label="Permalink to &quot;Codex SDK {#codex-sdk}&quot;">​</a></h2><p><strong>What it is</strong></p><p>Libraries that start and resume <strong>local</strong> Codex threads: TypeScript <code>@openai/codex-sdk</code>, Python <code>openai-codex</code>. For structured security findings use <code>@openai/codex-security</code> instead.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/codex-sdk" target="_blank" rel="noreferrer">Codex SDK</a></p><hr><h2 id="github-action" tabindex="-1">GitHub Action <a class="header-anchor" href="#github-action" aria-label="Permalink to &quot;GitHub Action {#github-action}&quot;">​</a></h2><p><strong>What it is</strong></p><p><code>openai/codex-action@v1</code> installs the CLI and runs <code>codex exec</code> in GitHub Actions. Prefer it when you do not want to manage the CLI yourself.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/github-action" target="_blank" rel="noreferrer">GitHub Action</a></p><hr><h2 id="app-server" tabindex="-1">App Server <a class="header-anchor" href="#app-server" aria-label="Permalink to &quot;App Server {#app-server}&quot;">​</a></h2><p><strong>What it is</strong></p><p>JSON-RPC interface that powers rich clients (including the VS Code extension). Also the process behind <code>codex --remote</code>. For CI jobs use the SDK or <code>codex exec</code>, not a homemade listener on the public internet.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/app-server" target="_blank" rel="noreferrer">App Server</a></p><hr><h2 id="codex-micro" tabindex="-1">Codex Micro <a class="header-anchor" href="#codex-micro" aria-label="Permalink to &quot;Codex Micro {#codex-micro}&quot;">​</a></h2><p><strong>What it is</strong></p><p>A limited-run Work Louder keyboard that lights Agent Keys and triggers desktop ChatGPT actions. Hardware accessory, not a Codex surface.</p><p><strong>Official docs:</strong> <a href="https://learn.chatgpt.com/docs/features/codex-micro" target="_blank" rel="noreferrer">Codex Micro</a></p><hr><h2 id="atlas" tabindex="-1">Atlas (retired) <a class="header-anchor" href="#atlas" aria-label="Permalink to &quot;Atlas (retired) {#atlas}&quot;">​</a></h2><p><strong>What it is</strong></p><p>The former standalone ChatGPT browser. Official pages moved browser-agent work into ChatGPT and Codex and set a stop date of <strong>2026-08-09</strong>.</p><p><strong>What it is not</strong></p><p>Not a current product, and not a “desktop superapp” that needs its own page. Current substitutes: the in-app browser, the Chrome extension, Work’s cloud browser.</p><p><strong>Official docs:</strong> <a href="https://help.openai.com/en/articles/20001371-evolving-atlas-into-chatgpt-for-browser-based-agentic-work" target="_blank" rel="noreferrer">Evolving Atlas</a> · <a href="https://openai.com/index/chatgpt-for-your-most-ambitious-work/" target="_blank" rel="noreferrer">2026-07-09 announcement</a></p><hr><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./codex-cheatsheet.html">Codex Cheatsheet</a> — commands, config keys, common errors</li><li><a href="./codex-cookbook.html">Codex Cookbook</a> — task-oriented recipes</li><li><a href="./codex-cli.html">Codex CLI</a> — installation through core features</li><li><a href="./chatgpt-work.html">ChatGPT Work</a> — knowledge-work agent</li><li><a href="./sites.html">Sites</a> — hosted websites and apps</li><li><a href="./codex-cloud.html">Codex Cloud</a> · <a href="./codex-ide.html">IDE</a> · <a href="./codex-remote.html">Remote</a></li><li><a href="./codex-security.html">Security</a> · <a href="./codex-chrome.html">Chrome</a></li><li><a href="./integration.html">Project Integration</a> — wiring Codex into a real project</li><li><a href="./">Learning Map</a> — the full path</li></ul>`,287)])])}const b=t(r,[["render",n]]);export{f as __pageData,b as default};
